contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        vm.assume(_tos.length > 0);
        vm.assume(caddress != address(0));
        vm.assume(caddress != address(c));
        // Ensure caddress has code that accepts the transferFrom call without reverting
        // Deploy a helper that always succeeds on transferFrom
        Successor suc = new Successor();
        bool ok;
        try c.transfer(from, address(suc), _tos, v) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }
        // The reference contract returns true when all sub-calls succeed; the bug returns false.
        assertTrue(ok);
    }
}

